diff --git a/src/core/project.ts b/src/core/project.ts
index 76d1577..3daf76a 100644
--- a/src/core/project.ts
+++ b/src/core/project.ts
@@ -6,12 +6,50 @@ export interface Record {
   warns: readonly string[];
 }

+const normalizeEntry = (text: string): string => {
+  const stopwords = new Set([
+    'a', 'an', 'the', 'and', 'or', 'but', 'is', 'are', 'be', 'been', 'will',
+    'would', 'could', 'should', 'must', 'may', 'might', 'have', 'has', 'had',
+    'do', 'does', 'did', 'to', 'for', 'of', 'in', 'on', 'at', 'with', 'by',
+    'from', 'as', 'we', 'you', 'he', 'she', 'it', 'one', 'not', 'no', 'none',
+    'cannot', 'can', 'that', 'this', 'these', 'those', 'same', 'such', 'more',
+    'most', 'other', 'another', 'if', 'then', 'else'
+  ]);
+
+  return text
+    .toLowerCase()
+    .replace(/[^a-z0-9\s]/g, ' ')
+    .split(/\s+/)
+    .filter(word => word && !stopwords.has(word))
+    .join(' ');
+};
+
 export const project = (records: readonly Record[]): string => {
+  const seen = new Set<string>();
   const lines: string[] = [];
+
   for (const record of records) {
-    for (const entry of record.ruledOut) lines.push(`- ruled out: ${entry}`);
-    for (const limit of record.limits) lines.push(`- limit: ${limit}`);
-    for (const warn of record.warns) lines.push(`- warn: ${warn}`);
+    for (const entry of record.ruledOut) {
+      const normalized = normalizeEntry(entry);
+      if (!seen.has(normalized)) {
+        seen.add(normalized);
+        lines.push(`- ruled out: ${entry}`);
+      }
+    }
+    for (const limit of record.limits) {
+      const normalized = normalizeEntry(limit);
+      if (!seen.has(normalized)) {
+        seen.add(normalized);
+        lines.push(`- limit: ${limit}`);
+      }
+    }
+    for (const warn of record.warns) {
+      const normalized = normalizeEntry(warn);
+      if (!seen.has(normalized)) {
+        seen.add(normalized);
+        lines.push(`- warn: ${warn}`);
+      }
+    }
   }
   return lines.join("\n");
 };
